import {Playground,HOMES,STATIONS,clamp} from './simulation.js';
import {createStudio} from './scene.js';
import {bindInteractions,destinations} from './interaction.js';
import {guide,GuidanceClock,cuePath,recovery} from './guidance.js';
import {StudioAudio} from './audio.js';
const sim=new Playground(),audio=new StudioAudio(),guidance=new GuidanceClock(),$=id=>document.getElementById(id);let studio,input,last=performance.now(),time=0,lastPose='',lastStep='',statusElapsed=0,errorTime=0,iceCount=0,keyboard=null,performanceTime=0,slowFrames=0;
const order=['grindPlace','grind','tamp','lock','cup','brew','extracting','cupFull','ice','milk','espresso','extraEspresso','sugar','stir','done','glassFull','served'];
function error(text){$('feedback').textContent=text;errorTime=4;}
function announce(){$('status').textContent=sim.summary;}
function reset(){input?.cancel();sim.reset();guidance.reset();audio.stop();keyboard=null;iceCount=0;lastPose=lastStep='';$('feedback').textContent='';errorTime=0;studio?.director.go('overview',{immediate:true});announce();}
function sound(){audio.enable(!audio.enabled);$('sound').setAttribute('aria-pressed',String(audio.enabled));$('sound').setAttribute('aria-label',audio.enabled?'Mute sound':'Enable sound');}
try{studio=createStudio($('scene'),sim);input=bindInteractions(studio,sim,{reset,toggleSound:sound,onChange:announce,onError:error});}catch(e){console.error(e);$('fallback').hidden=false;}
$('help').onclick=()=>guidance.show();$('recenter').onclick=()=>studio?.director.go('overview');$('sound').onclick=sound;$('reset').onclick=reset;$('new-drink').onclick=()=>{input?.cancel();sim.newDrink();guidance.reset();lastPose=lastStep='';announce();};$('skip').onclick=()=>{sim.skipSugar();announce();};
const actions=[['portafilter','Place portafilter under grinder','grinder'],['grindLever','Grinder. Hold Space to grind','grind'],['tamper','Tamp grounds. Enter to press','tamp'],['portafilter','Insert and lock portafilter. Enter','lock'],['cup','Place espresso cup. Enter','cup'],['brewLever','Brew. Enter starts or stops extraction','brew'],['iceScoop','Add four ice cubes with the scoop. Enter','ice'],['milk','Pour milk. Enter to pour automatically, hold Down for a partial pour','milk'],['cup','Pour espresso. Enter to pour automatically, hold Down for a partial pour','espresso'],['spoon','Sugar spoon. Enter scoops, Down adds sugar','sugar'],['spoon','Stir coffee. Hold Left or Right','stir'],['glass','Serve this glass. Enter','serve']];
function endKeyboard(){if(keyboard?.saved){if(sim.canPour(keyboard.from))sim.put(keyboard.from,keyboard.saved.position,keyboard.saved.slot);else sim.returnHome(keyboard.from);}if(keyboard?.action==='stir'&&sim.mixing>=.995)sim.returnHome('spoon');sim.stop({keepBrew:true,keepAutomatic:true});keyboard=null;announce();}
for(const[id,label,action]of actions){const b=document.createElement('button');b.type='button';b.setAttribute('aria-label',label);b.addEventListener('focus',()=>{studio?.director.interrupt();studio?.highlight(id);});b.addEventListener('blur',endKeyboard);b.addEventListener('keydown',e=>{if(!['Enter',' ','ArrowDown','ArrowLeft','ArrowRight','Escape'].includes(e.key))return;e.preventDefault();if(e.key==='Escape'){endKeyboard();sim.stop();return;}if(e.repeat)return;
 if(e.key==='Enter'){if(action==='grinder'&&sim.lock<.1)sim.dock('portafilter','grinder');if(action==='tamp'){sim.tamp(1);sim.returnHome('tamper');studio?.tampFeedback(sim.objects.portafilter.position);}if(action==='lock'){sim.dock('portafilter','group');sim.twist(1);}if(action==='cup')sim.dock('cup','brew');if(action==='brew'){if(sim.brewing)sim.brewing=false;else if(!sim.beginBrew())error(recovery(sim));}if(action==='ice')sim.addIceScoop();if(action==='milk'||action==='espresso')sim.autoPour(action==='milk'?'milk':'cup');if(action==='sugar')sim.scoop();if(action==='serve')sim.serveDrink();announce();return;}
 if(action==='grind'&&e.key===' ')sim.beginGrind();if(action==='sugar'&&e.key==='ArrowDown'){if(sim.addSugar())studio?.sugarBurst();else error('No room for more sugar. You can stir now.');sim.returnHome('spoon');}
 if(['milk','espresso'].includes(action)&&e.key==='ArrowDown'){const from=action==='milk'?'milk':'cup';if(!sim.canPour(from))return;const o=sim.objects[from],saved={position:[...o.position],slot:o.slot},m=studio.mouth('glass'),h=from==='cup'?.36:.79;sim.pick(from);o.position=[m[0]+Math.sin(1.1)*h,m[1]+.18-Math.cos(1.1)*h,m[2]];o.tilt=1.1;sim.pour(from,'glass',.8);keyboard={from,saved,key:e.key};return;}
 if(action==='stir'&&['ArrowLeft','ArrowRight'].includes(e.key)){sim.skipSugar();sim.put('spoon',studio.mouth('glass'),'stir');}keyboard={action,key:e.key};
 });b.addEventListener('keyup',e=>{if(keyboard?.key===e.key)endKeyboard();});$('keyboard-controls').appendChild(b);}
function updateGuide(dt){const g=guidance.update(sim,dt,!!input.active||!!keyboard);if(g.key!==lastStep){lastStep=g.key;errorTime=0;$('feedback').textContent='';$('title').textContent=g.title;$('instruction').textContent=g.text;$('phase').textContent=['glass','glassPour','hero'].includes(g.pose)?'THE ICED COFFEE':'THE ESPRESSO';$('skip').hidden=g.key!=='sugar';$('progress').style.width=`${order.indexOf(g.key)/(order.length-1)*100}%`;announce();}
 $('new-drink').hidden=!sim.served;$('detail').textContent=g.detail;$('instruction').textContent=g.text;if(g.pose!==lastPose&&!input.active&&!keyboard&&!sim.pouring){lastPose=g.pose;studio.director.go(g.pose);}
 if(!input.active){const path=cuePath(sim,g);studio.setTargets(g.key==='served'?[]:g.key==='done'||g.key==='glassFull'?[{position:STATIONS.coaster,radius:.39}]:g.key==='tamp'?[{position:sim.objects.tamper.position,radius:.18},{position:sim.objects.portafilter.position,radius:.23}]:[{position:path[1],radius:.22}]);}
 studio.setCue(!input.active&&guidance.cue>0?cuePath(sim,g):null,g.key);if(errorTime>0){errorTime-=dt;if(errorTime<=0)$('feedback').textContent='';}}
function frame(now){const raw=(now-last)/1000,dt=Math.min(raw,.05);last=now;if(!document.hidden&&studio){time+=dt;if(keyboard?.action==='stir')sim.stir(dt*3*(keyboard.key==='ArrowLeft'?-1:1),dt);sim.tick(dt);updateGuide(dt);const count=sim.ice.filter(c=>c.inside).length;if(count>iceCount)audio.clink();iceCount=count;audio.update(sim);studio.render(time,dt);statusElapsed+=dt;if(statusElapsed>1){statusElapsed=0;announce();}performanceTime+=dt;if(raw>.04)slowFrames++;if(performanceTime>5){if(slowFrames>60)studio.setQuality(true);performanceTime=slowFrames=0;}}requestAnimationFrame(frame);}
document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden){input?.cancel();endKeyboard();sim.stop();audio.stop();}});window.addEventListener('blur',()=>{endKeyboard();sim.stop();audio.stop();});announce();requestAnimationFrame(frame);
